    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    if not os.path.exists(session_file):
        return {}
    with open(session_file, 'r') as f:
        content = f.read()
    G = {}
    for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, h, w = match.groups()[1], int(match.groups()[2]), int(match.groups()[3])
        name = match.group(1).split()[1]
        if name not in G:
            rows = []
            remaining = content[match.end():]
            for line in remaining.split('\n')[:h]:
                if line.strip():
                    rows.append(list(map(int, line.split())))
            G[name] = rows
    return G

