# Try flood fill from edge 4s to determine which 4s are "enclosed"

def solve_by_flood_fill(inp):
    rows = len(inp)
    cols = len(inp[0])
    result = [list(r) for r in inp]

    # Start flood fill from all 4s at the edge
    visited = [[False]*cols for _ in range(rows)]
    queue = []

    for r in range(rows):
        for c in range(cols):
            if r == 0 or r == rows-1 or c == 0 or c == cols-1:
                if inp[r][c] == 4:
                    visited[r][c] = True
                    queue.append((r, c))

    idx = 0
    while idx < len(queue):
        r, c = queue[idx]
        idx += 1
        for nr, nc in [(r+1, c), (r-1, c), (r, c+1), (r, c-1)]:
            if 0 <= nr < rows and 0 <= nc < cols and inp[nr][nc] == 4 and not visited[nr][nc]:
                visited[nr][nc] = True
                queue.append((nr, nc))

    # All visited 4s stay the same, unvisited 4s become 2
    for r in range(rows):
        for c in range(cols):
            if inp[r][c] == 4 and not visited[r][c]:
                result[r][c] = 2

    return result

