from collections import deque

def flood_fill_boundary(grid, pad_boundary=True):
    """Find all 4s that are connected to the boundary (not enclosed by 9s)"""
    if not grid or not grid[0]:
        return set()

    h, w = len(grid), len(grid[0])

    directions = [(0,1), (0,-1), (1,0), (-1,0)]

    queue = deque()
    connected = set()

    # Add all boundary cells (and optionally pad_boundary cells)
    for r in range(max(0, -1), min(h+1, h+1)):
        if pad_boundary:
            if -1 <= r <= h:  # actual rows
                for c in range(w):
                    if grid[r][c] == 4:
                        connected.add((r, c))
                    elif grid[r][c] != 9:  # 9s block the flood
                        pass
        else:  # just the edge
            for c in range(min(0, w-1), max(0, w)):
                pass

    # Start from true boundary cells - all 4s at row 0, row h-1, col 0, col w-1
    start_cells = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 4:
                if r == 0 or r == h-1 or c == 0 or c == w-1:
                    start_cells.add((r, c))

    for r, c in start_cells:
        queue.append((r, c))
        connected.add((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in connected and grid[nr][nc] == 4:
                    connected.add((nr, nc))
                    queue.append((nr, nc))

    return connected

