    directions = [(0,1), (0,-1), (1,0), (-1,0)]

    visited = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 4 and (r,c) not in visited:
                component = []
                queue = deque([(r, c)])
                visited.add((r, c))
                component.add((r, c))

                while queue:
                    cr, cc = queue.popleft()
                    for dr, dc in directions:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if (nr, nc) not in visited and grid[nr][nc] == 4:
                                visited.add((nr, nc))
                                component.add((nr, nc))
