def is_between_9s_horizontal(cell_val, row, c, grid):
    """Check if grid[row][c] is 4 and horizontally between 9s"""
    if cell_val != 4:
        return False

    left_boundary = None
    right_boundary = None

    # Find left 9
    for dc in range(c-1, -1, -1):
        if grid[row][dc] == 9:
            left_boundary = dc
            break
        if grid[row][dc] == 4:
            continue
        # If we hit a non-9, non-4 before a 9, not between
        if dc < 0 or (grid[row][dc] == 4 and dc == 0):
            if left_boundary is None:
                return False

    # Find right 9
    for dc in range(c+1, len(row)):
        if grid[row][dc] == 9:
            right_boundary = dc
            break
        if grid[row][dc] == 4:
            continue

    if left_boundary is not None and right_boundary is not None:
        return True  # has 9 on both sides
    return False

def is_between_9s_vertical(cell_val, r, c, grid):
    """Check if grid[r][c] is 4 and vertically between 9s"""
    if cell_val != 4:
