    bottom_boundary = None

    # Find top 9
    for dr in range(r-1, -1, -1):
        if grid[dr][c] == 9:
            top_boundary = dr
            break

    # Find bottom 9
    for dr in range(r+1, len(grid)):
        if grid[dr][c] == 9:
            bottom_boundary = dr
            break

    if top_boundary is not None and bottom_boundary is not None:
        return True  # has 9 on both sides
    return False

