def transform_consecutive_between(grid):
    result = [[cell for cell in row] for row in grid]
    for r in range(len(grid)):
        nines = [c for c in range(len(grid[r])) if grid[r][c] == 9]
        if len(nines) >= 2:
            # For every pair of consecutive 9s, 4s between them become 2s
            for i in range(len(nines) - 1):
                start_9, end_9 = nines[i], nines[i+1]
                for c in range(start_9 + 1, end_9):
                    if grid[r][c] == 4:
                        result[r][c] = 2
    return result

