# The transform applies to demo input
def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [[cell for cell in row] for row in grid]

    for r in range(rows):
        nines = [c for c in range(cols) if grid[r][c] == 9]

        # Rule 1: 2+ nines
        if len(nines) >= 2:
            for i in range(len(nines) - 1):
                start_9, end_9 = nines[i], nines[i+1]
                if start_9 == 0 and end_9 == 13:
                    continue
                for c in range(start_9 + 1, end_9):
                    if grid[r][c] == 4:
                        result[r][c] = 2

        # Rule 2 & 3: single 9 at edge
        if len(nines) == 1:
            if nines[0] == 13:
                if result[r][0] == 4:
                    result[r][0] = 2
            elif nines[0] == 0:
                if result[r][13] == 4:
                    result[r][13] = 2

    return result

